const state={workspaceAccountExists:false,signedIn:false,requiresLogin:false,setupPersisted:false,workspaceSettingsOpen:false,setupStep:"account",tab:"overview",editingAccountId:"",operator:{marvinDisplayName:"",marvinEmail:"",marvinPassword:""},profileName:"marvin.local",timezone:"America/New_York",syncWindowDays:45,accounts:[],preferences:{defaultDetailMode:"full",defaultVisibility:"private",familyDetailMode:"full",familyVisibility:"private",subjectPrefix:"SRC: ",copyLocationToFamily:true,copyDescriptionToFamily:true,preserveOriginalTimezone:true},providerCredentials:{microsoftClientId:"",googleClientId:""},providerSecrets:{microsoftClientSecret:"",googleClientSecret:""},providerSecretStatus:{microsoftClientSecretConfigured:false,googleClientSecretConfigured:false,caldavPasswordConfigured:false,caldavPasswordsConfigured:{}},providerConnections:{},providerRequirements:{},providerPlans:{microsoft:null,google:null},connectionSummary:null,tokenSummary:null,readinessSummary:null,runtimeStatus:null,runtimeProcess:null,subscriptionState:null,authWatch:null};
