function setStatus(text,tone="ok"){statusEl.textContent=text;statusEl.className=`status ${tone}`}
function stopAuthWatch(){if(state.authWatch?.timer)clearInterval(state.authWatch.timer);state.authWatch=null}
async function postJson(url,body){const response=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});return response.json()}
async function getJson(url){const response=await fetch(url);return response.json()}
async function loadProviderPlan(provider){if(!state.setupPersisted){alert("Save Marvin setup first.");return null}const result=await getJson(`/marvin-api/provider-plan?profileName=${encodeURIComponent(state.profileName)}&provider=${encodeURIComponent(provider)}`);if(!result.ok){setStatus(result.error||`Unable to load the ${providerLabel(provider==="microsoft"?"m365":"google")} app plan.`,"bad");return null}state.providerPlans={...state.providerPlans,[provider]:result};setStatus(`${provider==="microsoft"?"Microsoft":"Google"} app plan loaded from Marvin.`,"ok");render();return result}
function buildProviderSecretsPayload(accounts=state.accounts){const caldavPasswords={};for(const account of accounts){if(account.provider==="apple-caldav"&&account.caldavPassword){caldavPasswords[sanitize(account.id||account.email)]=account.caldavPassword}}return{microsoftClientSecret:state.providerSecrets.microsoftClientSecret||"",googleClientSecret:state.providerSecrets.googleClientSecret||"",caldavPasswords}}
function applyConfig(config){if(!config)return;state.profileName=config.profileName||state.profileName;state.accounts=config.accounts||[];state.preferences={...state.preferences,...(config.preferences||{})};state.providerCredentials={...state.providerCredentials,...(config.providerCredentials||{})};state.providerConnections=config.providerConnections||state.providerConnections;state.providerSecretStatus=config.providerSecretStatus||state.providerSecretStatus;state.providerRequirements=config.providerRequirements||{};state.connectionSummary=config.connectionSummary||null;state.tokenSummary=config.tokenSummary||null;state.readinessSummary=config.readinessSummary||null;state.runtimeStatus=config.runtimeStatus||null;state.runtimeProcess=config.runtimeProcess||null;state.subscriptionState=config.subscriptionState||state.subscriptionState||null;state.setupPersisted=true;if(config.marvinOperator)state.operator.marvinEmail=config.marvinOperator;if(config.marvinDisplayName)state.operator.marvinDisplayName=config.marvinDisplayName;if(config.timezone)state.timezone=config.timezone;if(config.syncWindowDays)state.syncWindowDays=Number(config.syncWindowDays)||state.syncWindowDays;state.providerSecrets.microsoftClientSecret="";state.providerSecrets.googleClientSecret=""}
function currentConfigPayload(accounts=state.accounts){return{profileName:state.profileName,marvinEmail:state.operator.marvinEmail,marvinAccount:{email:state.operator.marvinEmail,displayName:state.operator.marvinDisplayName,timezone:state.timezone},timezone:state.timezone,syncWindowDays:state.syncWindowDays,accounts,preferences:state.preferences,providerConnections:state.providerConnections,providerCredentials:state.providerCredentials,deployment:{marvinUrl:window.location.origin}}}
function syncWorkspaceFromDom(){state.operator.marvinDisplayName=(document.getElementById("workspaceDisplayName")?.value||state.operator.marvinDisplayName||"").trim();state.operator.marvinEmail=(document.getElementById("workspaceEmail")?.value||state.operator.marvinEmail||"").trim();const password=(document.getElementById("workspacePassword")?.value||"").trim();if(password)state.operator.marvinPassword=password;const profileId=document.getElementById("workspaceProfileName")?.value;if(profileId)state.profileName=sanitize(profileId.trim());const timezone=document.getElementById("workspaceTimezone")?.value;if(timezone)state.timezone=timezone.trim();const syncWindowDays=document.getElementById("workspaceSyncWindowDays")?.value;if(syncWindowDays)state.syncWindowDays=Number(syncWindowDays)||state.syncWindowDays;state.preferences.defaultDetailMode=document.getElementById("policyDefaultDetailMode")?.value||state.preferences.defaultDetailMode;state.preferences.defaultVisibility=document.getElementById("policyDefaultVisibility")?.value||state.preferences.defaultVisibility;state.preferences.familyDetailMode=document.getElementById("policyFamilyDetailMode")?.value||state.preferences.familyDetailMode;state.preferences.familyVisibility=document.getElementById("policyFamilyVisibility")?.value||state.preferences.familyVisibility;state.preferences.copyLocationToFamily=Boolean(document.getElementById("policyCopyLocationToFamily")?.checked??state.preferences.copyLocationToFamily);state.preferences.copyDescriptionToFamily=Boolean(document.getElementById("policyCopyDescriptionToFamily")?.checked??state.preferences.copyDescriptionToFamily);state.preferences.preserveOriginalTimezone=Boolean(document.getElementById("policyPreserveOriginalTimezone")?.checked??state.preferences.preserveOriginalTimezone);state.providerCredentials.microsoftClientId=(document.getElementById("microsoftClientId")?.value||state.providerCredentials.microsoftClientId||"").trim();state.providerCredentials.googleClientId=(document.getElementById("googleClientId")?.value||state.providerCredentials.googleClientId||"").trim();state.providerSecrets.microsoftClientSecret=(document.getElementById("microsoftClientSecret")?.value||"").trim();state.providerSecrets.googleClientSecret=(document.getElementById("googleClientSecret")?.value||"").trim()}
function buildAccountFromForm(){const editing=currentAccount();const provider=document.getElementById("accountProvider")?.value||editing?.provider||"m365";const label=(document.getElementById("accountLabel")?.value||editing?.label||"").trim();const email=(document.getElementById("accountEmail")?.value||editing?.email||"").trim();const scope=(document.getElementById("accountScope")?.value||editing?.scope||"work").trim();const sourcePrefix=(document.getElementById("accountPrefix")?.value||editing?.sourcePrefix||"").trim()||defaultPrefix(label,provider);const inbound={visibility:document.getElementById("accountVisibility")?.value||editing?.inboundOverrides?.visibility||"",detailMode:document.getElementById("accountDetailMode")?.value||editing?.inboundOverrides?.detailMode||"",copyLocation:Boolean(document.getElementById("accountCopyLocation")?.checked),copyDescription:Boolean(document.getElementById("accountCopyDescription")?.checked)};if(!inbound.visibility)delete inbound.visibility;if(!inbound.detailMode)delete inbound.detailMode;return{id:editing?.id||sanitize(`${provider}-${email||label||Date.now()}`),label,email,provider,scope,sourcePrefix,inboundOverrides:Object.keys(inbound).length?inbound:undefined,caldavServerUrl:(document.getElementById("accountCaldavServerUrl")?.value||editing?.caldavServerUrl||"").trim(),caldavUsername:(document.getElementById("accountCaldavUsername")?.value||editing?.caldavUsername||email).trim(),caldavPassword:(document.getElementById("accountCaldavPassword")?.value||"").trim(),connectionStatus:editing?.connectionStatus||"pending",connectedAt:editing?.connectedAt||""}}
function accountSummary(account){return{access:providerAccessConfigured(account)?"ready":"needs setup",link:accountStatusLabel(account)}}
function providerAccessSummaryMarkup(){return`<div class="list"><div class="note"><strong>Microsoft app status:</strong> ${state.providerCredentials.microsoftClientId?"client ID saved":"client ID missing"}; ${state.providerSecretStatus.microsoftClientSecretConfigured?"client secret stored locally":"client secret missing"}</div><div class="note"><strong>Google app status:</strong> ${state.providerCredentials.googleClientId?"client ID saved":"client ID missing"}; ${state.providerSecretStatus.googleClientSecretConfigured?"client secret stored locally":"client secret missing"}</div><div class="note"><strong>Apple / CalDAV:</strong> app passwords are stored per calendar account inside Marvin.</div></div>`}
function accountCard(account){const summary=accountSummary(account);const connectLabel=account.provider==="apple-caldav"?"Validate Apple Access":accountStatus(account)==="connected"?"Reconnect Account":"Link Account";const linkedIdentity=account.linkedAccountEmail||account.linkedAccountName||account.linkedAccountRef||"";const proofStatus=account.authEvidence||account.tokenReason||account.connectionReason||"";return`<article class="account"><header><div><div class="chip">${esc(providerLabel(account.provider))}</div><h4>${esc(account.label)}</h4><p>${esc(account.email)}${account.scope?` · ${esc(account.scope)}`:""}</p></div><div class="buttons"><span class="badge ${badgeClass(accountStatus(account))}">${esc(accountStatusLabel(account))}</span><span class="badge ${badgeClass(account.readinessState||"pending")}">${esc(account.readinessLabel||"Action Required")}</span></div></header><div class="grid"><div class="note"><strong>Access setup:</strong> ${esc(summary.access)}</div><div class="note"><strong>Link status:</strong> ${esc(summary.link)}</div><div class="note"><strong>Token status:</strong> ${esc(tokenStatus(account))}</div><div class="note"><strong>Prefix:</strong> ${esc(account.sourcePrefix||defaultPrefix(account.label,account.provider))}</div></div><p class="meta">${esc(account.readinessDetail||account.connectionReason||"")}</p><dl><div><dt>Linked identity</dt><dd>${esc(linkedIdentity||"not proven yet")}</dd></div><div><dt>Last validated</dt><dd>${esc(formatWhen(account.lastValidatedAt)||"not yet")}</dd></div><div><dt>OAuth callback</dt><dd>${esc(formatWhen(account.authCallbackReceivedAt)||"not yet")}</dd></div><div><dt>Token obtained</dt><dd>${esc(formatWhen(account.tokenObtainedAt)||"not yet")}</dd></div><div><dt>Connected at</dt><dd>${esc(formatWhen(account.connectedAt)||"not yet")}</dd></div><div><dt>Visibility override</dt><dd>${esc(account.inboundOverrides?.visibility||"default policy")}</dd></div><div><dt>Detail override</dt><dd>${esc(account.inboundOverrides?.detailMode||"default policy")}</dd></div><div><dt>Auth proof</dt><dd>${esc(proofStatus||"No provider proof recorded yet.")}</dd></div></dl><div class="actions compact-actions"><button data-action="connect" data-id="${esc(account.id)}">${connectLabel}</button><button class="secondary" data-action="validate" data-id="${esc(account.id)}">Check Access</button><button class="secondary" data-action="edit" data-id="${esc(account.id)}">Edit Calendar</button><button class="ghost" data-action="remove" data-id="${esc(account.id)}">Remove Calendar</button></div></article>`}
function bindAccountActions(root){if(!root)return;root.querySelectorAll("[data-action='connect']").forEach((button)=>button.addEventListener("click",()=>{void beginConnect(button.dataset.id)}));root.querySelectorAll("[data-action='validate']").forEach((button)=>button.addEventListener("click",()=>{void validateAccount(button.dataset.id)}));root.querySelectorAll("[data-action='edit']").forEach((button)=>button.addEventListener("click",()=>{state.editingAccountId=button.dataset.id;if(!state.setupPersisted||state.workspaceSettingsOpen){state.setupStep="calendars"}else{state.tab="calendars"}render()}));root.querySelectorAll("[data-action='remove']").forEach((button)=>button.addEventListener("click",()=>removeAccount(button.dataset.id)))}
async function reloadConfig(options={}){if(!state.profileName||state.profileName==="marvin.local")return null;const result=await getJson(`/marvin-api/config?profileName=${encodeURIComponent(state.profileName)}`);if(!result.ok){if(!options.silent)setStatus(result.error||"Unable to refresh Marvin state.","bad");return null}if(result.config)applyConfig(result.config);if(!options.silent)setStatus(options.statusText||"Marvin state refreshed.","ok");render();return result.config||null}
async function createWorkspaceAccount(){syncWorkspaceFromDom();if(!state.operator.marvinDisplayName||!state.operator.marvinEmail){alert("Enter a Marvin account name and email.");return false}if(!state.workspaceAccountExists&&!state.operator.marvinPassword){alert("Enter a local Marvin password.");return false}const result=await postJson("/marvin-api/create-account",{marvinDisplayName:state.operator.marvinDisplayName,marvinEmail:state.operator.marvinEmail,marvinPassword:state.operator.marvinPassword});if(!result.ok){alert(result.error||"Unable to create the Marvin account.");setStatus(result.error||"Unable to create the Marvin account.","bad");return false}state.workspaceAccountExists=true;state.signedIn=true;state.requiresLogin=false;state.setupStep="calendars";if(result.operator){state.operator.marvinDisplayName=result.operator.displayName||state.operator.marvinDisplayName;state.operator.marvinEmail=result.operator.email||state.operator.marvinEmail}if(result.config)applyConfig(result.config);setStatus("Marvin account saved. Continue with calendar setup.","ok");render();return true}
async function signInWorkspace(){const email=(document.getElementById("workspaceEmail")?.value||state.operator.marvinEmail||"").trim();const password=(document.getElementById("workspacePassword")?.value||"").trim();if(!email||!password){alert("Enter the Paranoid Keeper workspace email and password.");return}const result=await postJson("/marvin-api/login",{marvinEmail:email,marvinPassword:password});if(!result.ok){alert(result.error||"Unable to sign in to Marvin.");setStatus(result.error||"Unable to sign in to Marvin.","bad");return}state.workspaceAccountExists=true;state.signedIn=true;state.requiresLogin=false;state.setupStep="calendars";if(result.operator){state.operator.marvinDisplayName=result.operator.displayName||state.operator.marvinDisplayName;state.operator.marvinEmail=result.operator.email||state.operator.marvinEmail}if(result.config)applyConfig(result.config);setStatus("Signed in to Marvin.","ok");render()}
async function signOutWorkspace(){const result=await postJson("/marvin-api/logout",{});stopAuthWatch();state.signedIn=false;state.requiresLogin=state.workspaceAccountExists;state.setupPersisted=false;state.workspaceSettingsOpen=false;state.setupStep="account";state.accounts=[];state.connectionSummary=null;state.tokenSummary=null;state.readinessSummary=null;state.runtimeStatus=null;state.runtimeProcess=null;state.subscriptionState=null;setStatus(result.ok?"Signed out of Marvin.":"Signed out of Marvin with local state cleared.","warn");render()}
async function saveLocalAccount(){const account=buildAccountFromForm();if(!account.label||!account.email){alert("Add at least a calendar label and email.");return}if(account.provider==="apple-caldav"&&!account.caldavServerUrl){alert("Apple / CalDAV accounts need a server URL.");return}if(account.provider==="apple-caldav"&&!account.caldavUsername){alert("Apple / CalDAV accounts need a username.");return}const index=state.accounts.findIndex((item)=>item.id===account.id);const nextAccounts=index>=0?state.accounts.map((item,idx)=>idx===index?{...item,...account}:item):[...state.accounts,account];if(!state.setupPersisted){state.accounts=nextAccounts;state.editingAccountId="";setStatus(index>=0?"Calendar updated in Marvin staging.":"Calendar added to Marvin staging.","ok");render();return}const result=await postJson("/marvin-api/account-upsert",{...currentConfigPayload(nextAccounts),providerSecrets:buildProviderSecretsPayload(nextAccounts),account});if(!result.ok){alert(result.error||"Unable to save the calendar.");setStatus(result.error||"Unable to save the calendar.","bad");return}if(result.config)applyConfig(result.config);state.editingAccountId="";setStatus(index>=0?"Calendar updated in Marvin.":"Calendar added to Marvin.","ok");render()}
async function removeAccount(id){const account=state.accounts.find((item)=>item.id===id);if(!account)return;if(!confirm(`Remove ${account.label} from Marvin?`))return;if(!state.setupPersisted){state.accounts=state.accounts.filter((item)=>item.id!==id);if(state.editingAccountId===id)state.editingAccountId="";setStatus("Calendar removed from Marvin staging.","ok");render();return}const result=await postJson("/marvin-api/account-remove",{profileName:state.profileName,accountId:id});if(!result.ok){alert(result.error||"Unable to remove the calendar.");setStatus(result.error||"Unable to remove the calendar.","bad");return}if(result.config)applyConfig(result.config);if(state.editingAccountId===id)state.editingAccountId="";setStatus("Calendar removed from Marvin.","ok");render()}
async function saveSetup(openConsole=false){syncWorkspaceFromDom();if(!state.workspaceAccountExists){const created=await createWorkspaceAccount();if(!created)return}if(!state.accounts.length){alert("Add at least one calendar before saving Marvin setup.");return}const result=await postJson("/marvin-api/save-config",{...currentConfigPayload(state.accounts),providerSecrets:buildProviderSecretsPayload()});if(!result.ok){alert(result.error||"Unable to save Marvin setup.");setStatus(result.error||"Unable to save Marvin setup.","bad");return}applyConfig(result.config);if(openConsole){state.workspaceSettingsOpen=false;state.tab="overview"}setStatus("Paranoid Keeper workspace saved. Link each calendar and validate access before starting automation.","ok");render()}
async function saveProviderAccessOnly(){if(!state.setupPersisted){alert("Save Marvin setup first.");return}syncWorkspaceFromDom();const result=await postJson("/marvin-api/provider-config",{profileName:state.profileName,providerCredentials:state.providerCredentials,providerSecrets:buildProviderSecretsPayload(),providerConnections:state.providerConnections,deployment:{}});if(!result.ok){alert(result.error||"Unable to save calendar access settings.");setStatus(result.error||"Unable to save calendar access settings.","bad");return}if(result.config)applyConfig(result.config);setStatus("Calendar access settings saved in Marvin.","ok");render()}
function startAuthWatch(calendarId,label){stopAuthWatch();let attempts=0;state.authWatch={calendarId,label,timer:setInterval(async()=>{attempts+=1;const config=await reloadConfig({silent:true});const live=(config?.accounts||state.accounts).find((item)=>item.id===calendarId);if(!live){if(attempts>=40)stopAuthWatch();return}if(live.connectionStatus==="connected"&&live.tokenStatus==="usable"){setStatus(`${label} is linked and validated in Marvin.`,"ok");stopAuthWatch();return}if(live.authCallbackReceivedAt){setStatus(`${label} returned to Marvin at ${formatWhen(live.authCallbackReceivedAt)}. Waiting for final token or validation state.`,"warn")}else if(attempts===1||attempts%5===0){setStatus(`Waiting for ${label} to return from provider sign-in. Marvin is checking local state automatically.`,"warn")}if(attempts>=40){setStatus(`Stopped waiting for ${label}. Use Refresh Marvin State if sign-in finished in another window.`,"warn");stopAuthWatch()}},3000)}}
async function beginConnect(accountId){if(!state.setupPersisted){alert("Save Marvin setup first.");return}const account=state.accounts.find((item)=>item.id===accountId);if(!account)return;if(account.provider==="apple-caldav"&&!account.caldavPasswordConfigured&&!account.caldavPassword){state.editingAccountId=account.id;state.workspaceSettingsOpen=true;state.setupStep="calendars";setStatus(`${account.label} still needs Apple / CalDAV credentials in Marvin before validation can run.`,"warn");render();return}const result=await postJson("/marvin-api/connection-begin",{profileName:state.profileName,calendarId:accountId});if(!result.ok){alert(result.error||"Unable to begin provider connection.");setStatus(result.error||"Unable to begin provider connection.","bad");return}if(result.config)applyConfig(result.config);const live=(result.config?.accounts||state.accounts).find((item)=>item.id===accountId)||account;const launchUrl=result.launchUrl||live.authUrl||"";if(!launchUrl){setStatus(result.message||`${account.label} is not ready to open provider sign-in yet. Review access setup and link status first.`,result.connectionRecord?.status==="connected"?"ok":"warn");render();return}window.open(launchUrl,"_blank","noopener");startAuthWatch(accountId,account.label);setStatus(`Opened the real ${providerLabel(account.provider)} sign-in for ${account.label}. Finish that page, return to Marvin, then run Check Access.`,"ok");render()}
async function validateAccount(accountId){if(!state.setupPersisted){alert("Save Marvin setup first.");return}const result=await postJson("/marvin-api/connection-validate",{profileName:state.profileName,calendarId:accountId});if(!result.ok){alert(result.error||"Unable to validate calendar access.");setStatus(result.error||"Unable to validate calendar access.","bad");return}if(result.config)applyConfig(result.config);setStatus(result.validation?.message||"Calendar validation completed.",result.validation?.ok?"ok":result.validation?.status==="pending"?"warn":"bad");render()}
async function validateAllConnections(){if(!state.setupPersisted){alert("Save Marvin setup first.");return}const result=await postJson("/marvin-api/connection-validate-all",{profileName:state.profileName});if(!result.ok){alert(result.error||"Unable to validate all calendar access.");setStatus(result.error||"Unable to validate all calendar access.","bad");return}if(result.config)applyConfig(result.config);state.runtimeStatus=result.runtimeStatus||state.runtimeStatus;state.runtimeProcess=result.runtimeProcess||state.runtimeProcess;const summary=result.validationSummary||{};const tone=Number(summary.invalid||0)>0?"warn":Number(summary.pending||0)>0?"warn":"ok";const runtimeMessage=result.runtimeStarted?" Paranoid Keeper background sync is running.":result.runtimeStartError?` ${result.runtimeStartError}`:"";setStatus(`Paranoid Keeper validated ${summary.total||0} calendars: ${summary.connected||0} connected, ${summary.pending||0} pending, ${summary.invalid||0} invalid.${runtimeMessage}`,tone);render()}
async function refreshRuntimeStatus(){if(!state.setupPersisted)return;const result=await getJson(`/marvin-api/runtime-status?profileName=${encodeURIComponent(state.profileName)}`);if(result.ok){state.runtimeStatus=result.runtimeStatus||null;state.runtimeProcess=result.runtimeProcess||null;state.subscriptionState=result.subscriptionState||state.subscriptionState||null;render()}}
async function startRuntime(){if(!state.setupPersisted){alert("Save Marvin setup first.");return}if(!automationReady()){const message=nextSteps().join(" ")||"Finish provider linking and validation for every calendar first.";alert(message);setStatus(`Marvin cannot start the Paranoid Keeper runtime yet. ${message}`,"warn");return}const result=await postJson("/marvin-api/runtime-start",{profileName:state.profileName,intervalSeconds:300,windowDays:state.syncWindowDays});if(!result.ok){alert(result.error||"Unable to start the Paranoid Keeper runtime.");setStatus(result.error||"Unable to start the Paranoid Keeper runtime.","bad");return}if(result.config)applyConfig(result.config);state.runtimeStatus=result.runtimeStatus||state.runtimeStatus;state.runtimeProcess=result.runtimeProcess||state.runtimeProcess;setStatus("Paranoid Keeper runtime started.","ok");render()}
async function stopRuntime(){if(!state.setupPersisted)return;const result=await postJson("/marvin-api/runtime-stop",{profileName:state.profileName});if(!result.ok){alert(result.error||"Unable to stop the Paranoid Keeper runtime.");setStatus(result.error||"Unable to stop the Paranoid Keeper runtime.","bad");return}if(result.config)applyConfig(result.config);state.runtimeStatus=result.runtimeStatus||state.runtimeStatus;state.runtimeProcess=result.runtimeProcess||state.runtimeProcess;setStatus("Paranoid Keeper runtime stopped.","ok");render()}
function workspaceSummary(){const automation=state.subscriptionState?.automation||{};const queued=automation.pendingSyncRequested?`queued from ${esc(automation.lastRequestedByProvider||"provider")} webhook${automation.lastRequestedByCalendarIds?.length?` for ${esc(automation.lastRequestedByCalendarIds.join(", "))}`:""}`:"no queued webhook wake";return`<div class="note"><strong>Workspace Account:</strong> ${esc(state.operator.marvinDisplayName||"Marvin Workspace")} (${esc(state.operator.marvinEmail||"not set")})</div><div class="note"><strong>Workspace profile:</strong> <span class="mono">${esc(state.profileName)}</span></div><div class="note"><strong>Timezone:</strong> ${esc(state.timezone)}</div><div class="note"><strong>Sync window:</strong> ${esc(state.syncWindowDays)} days</div><div class="note"><strong>Paranoid Keeper runtime:</strong> ${state.runtimeProcess?.running?"running":"stopped"}</div><div class="note"><strong>Webhook wake queue:</strong> ${queued}</div>`}
function readinessSummary(){const summary=state.connectionSummary?.summary||{total:state.accounts.length,connected:0,pending:state.accounts.filter((item)=>accountStatus(item)!=="connected").length,invalid:0,connectorNotReady:0};const token=state.tokenSummary||{usable:0};const readiness=state.readinessSummary||{ready:0,actionRequired:state.accounts.length,readyToStartAutomation:false};return`<div class="note"><strong>Ready:</strong> ${readiness.ready}</div><div class="note"><strong>Action Required:</strong> ${readiness.actionRequired}</div><div class="note"><strong>Connected:</strong> ${summary.connected}</div><div class="note"><strong>Pending auth:</strong> ${summary.pending}</div><div class="note"><strong>Invalid:</strong> ${summary.invalid}</div><div class="note"><strong>Connector not ready:</strong> ${summary.connectorNotReady}</div><div class="note"><strong>Usable tokens:</strong> ${token.usable||0}</div><div class="note"><strong>Keeper start status:</strong> ${readiness.readyToStartAutomation?"Ready":"Blocked"}</div>`}
function runtimeSummary(){const runtime=state.runtimeStatus;const process=state.runtimeProcess;const automation=state.subscriptionState?.automation||{};if(!runtime)return`<div class="note"><strong>Paranoid Keeper runtime:</strong> No Paranoid Keeper runtime status has been recorded yet.</div><div class="note"><strong>Process:</strong> ${process?.running?`running (PID ${process.pid})`:"stopped"}</div><div class="note"><strong>Queued webhook wake:</strong> ${automation.pendingSyncRequested?`yes, ${esc(automation.lastRequestedByProvider||"provider")} at ${esc(formatWhen(automation.lastRequestedAt)||automation.lastRequestedAt||"unknown time")}`:"none"}</div>`;const last=runtime.lastResult||null;return`<div class="note"><strong>Paranoid Keeper runtime:</strong> ${runtime.running?"running":"stopped"}</div><div class="note"><strong>Process:</strong> ${process?.running?`running (PID ${process.pid})`:"stopped"}</div><div class="note"><strong>Interval:</strong> ${runtime.intervalSeconds||0} seconds</div><div class="note"><strong>Run count:</strong> ${runtime.runCount||0}</div><div class="note"><strong>Last started:</strong> ${esc(runtime.lastStartedAt||"never")}</div><div class="note"><strong>Last completed:</strong> ${esc(runtime.lastCompletedAt||"never")}</div><div class="note"><strong>Last wake reason:</strong> ${esc(runtime.lastWakeReason||last?.wakeReason||"interval")}</div><div class="note"><strong>Queued webhook wake:</strong> ${automation.pendingSyncRequested?`yes, ${esc(automation.lastRequestedByProvider||"provider")} at ${esc(formatWhen(automation.lastRequestedAt)||automation.lastRequestedAt||"unknown time")}`:"none"}</div>${last?.webhookTrigger?`<div class="note"><strong>Last webhook trigger:</strong> ${esc(last.webhookTrigger.provider||"provider")} ${last.webhookTrigger.calendarIds?.length?`for ${esc(last.webhookTrigger.calendarIds.join(", "))}`:""}</div>`:""}${last?.applyResult?`<div class="note"><strong>Last sync result:</strong> ${last.applyResult.succeeded} succeeded, ${last.applyResult.failed} failed, ${last.applyResult.skipped} skipped</div>`:""}`}
function providerRequirementsMarkup(){const requirements=state.providerRequirements||{};const microsoft=requirements.microsoft||{};const google=requirements.google||{};const microsoftPerms=Array.isArray(microsoft.delegatedPermissions)?microsoft.delegatedPermissions.map((item)=>item.name).join(", "):"";const googleScopes=Array.isArray(google.scopes)?google.scopes.join(", "):"";return`<div class="list"><div class="note"><strong>Microsoft redirect URI:</strong> <span class="mono">${esc(microsoft.redirectUri||"save Marvin setup first")}</span></div><div class="note"><strong>Microsoft start URL:</strong> <span class="mono">${esc(microsoft.startUrl||"save Marvin setup first")}</span></div><div class="note"><strong>Microsoft delegated permissions:</strong> ${esc(microsoftPerms||"User.Read, Calendars.ReadWrite")}</div><div class="note"><strong>Google redirect URI:</strong> <span class="mono">${esc(google.redirectUri||"save Marvin setup first")}</span></div><div class="note"><strong>Google start URL:</strong> <span class="mono">${esc(google.startUrl||"save Marvin setup first")}</span></div><div class="note"><strong>Google scopes:</strong> ${esc(googleScopes||"openid, email, profile, https://www.googleapis.com/auth/calendar")}</div></div>`}
function providerPlanCard(provider){const result=state.providerPlans?.[provider];const label=provider==="microsoft"?"Microsoft":"Google";if(!result?.plan){return `<div class="note"><strong>${label} app plan:</strong> Not loaded yet.</div>`}const plan=result.plan||{};return `<div class="note"><strong>${label} helper command:</strong> <span class="mono">${esc(result.helperCommand||"")}</span></div><div class="note"><strong>${label} redirect URI:</strong> <span class="mono">${esc(plan.redirectUri||"")}</span></div><div class="note"><strong>${label} authorize path:</strong> <span class="mono">${esc(plan.authorizePath||"")}</span></div>${plan.creationMode?`<div class="note"><strong>${label} creation mode:</strong> ${esc(plan.creationMode)}</div>`:""}`}
function providerPlanSectionMarkup(){return `<details class="details-block"><summary>Provider admin details</summary><p class="meta">Only use this section when Marvin says Microsoft or Google access setup is still missing. Most operators can stay in the calendar list above.</p><div class="actions"><button id="loadMicrosoftPlan" class="secondary">Load Microsoft Admin Details</button><button id="loadGooglePlan" class="secondary">Load Google Admin Details</button></div><div class="list">${providerAccessSummaryMarkup()}${providerRequirementsMarkup()}${providerPlanCard("microsoft")}${providerPlanCard("google")}</div></details>`}
function accountForm(editing){return`<div class="fields"><div class="field"><label>Calendar label</label><input id="accountLabel" value="${esc(editing?.label||"")}" placeholder="Work"></div><div class="field"><label>Provider</label><select id="accountProvider"><option value="m365" ${(editing?.provider||"m365")==="m365"?"selected":""}>Microsoft 365</option><option value="outlook" ${editing?.provider==="outlook"?"selected":""}>Outlook</option><option value="google" ${editing?.provider==="google"?"selected":""}>Google Calendar</option><option value="apple-caldav" ${editing?.provider==="apple-caldav"?"selected":""}>Apple / CalDAV</option></select></div><div class="field"><label>Calendar email</label><input id="accountEmail" value="${esc(editing?.email||"")}" placeholder="work@example.com"></div><div class="field"><label>Calendar scope</label><select id="accountScope"><option value="work" ${(editing?.scope||"work")==="work"?"selected":""}>work</option><option value="family" ${editing?.scope==="family"?"selected":""}>family</option><option value="contract" ${editing?.scope==="contract"?"selected":""}>contract</option><option value="personal" ${editing?.scope==="personal"?"selected":""}>personal</option></select></div><div class="field"><label>Source prefix</label><input id="accountPrefix" value="${esc(editing?.sourcePrefix||"")}" placeholder="WORK: "></div><div class="field"><label>Inbound visibility override</label><select id="accountVisibility"><option value="">Use default</option><option value="private" ${editing?.inboundOverrides?.visibility==="private"?"selected":""}>private</option><option value="default" ${editing?.inboundOverrides?.visibility==="default"?"selected":""}>default</option></select></div><div class="field"><label>Inbound detail override</label><select id="accountDetailMode"><option value="">Use default</option><option value="busy" ${editing?.inboundOverrides?.detailMode==="busy"?"selected":""}>busy</option><option value="subject" ${editing?.inboundOverrides?.detailMode==="subject"?"selected":""}>subject</option><option value="full" ${editing?.inboundOverrides?.detailMode==="full"?"selected":""}>full</option></select></div><div class="field"><label>Apple / CalDAV server URL</label><input id="accountCaldavServerUrl" value="${esc(editing?.caldavServerUrl||"")}" placeholder="https://caldav.example.com/user"></div><div class="field"><label>Apple / CalDAV username</label><input id="accountCaldavUsername" value="${esc(editing?.caldavUsername||"")}" placeholder="apple@example.com"></div><div class="field full"><label>Apple / CalDAV app password</label><input id="accountCaldavPassword" type="password" placeholder="Leave blank to keep the stored password"></div></div><div class="toggle"><label class="check"><input id="accountCopyLocation" type="checkbox" ${(editing?.inboundOverrides?.copyLocation??true)?"checked":""}><span>Allow location on this target</span></label><label class="check"><input id="accountCopyDescription" type="checkbox" ${(editing?.inboundOverrides?.copyDescription??true)?"checked":""}><span>Allow description on this target</span></label></div>`}
function rulesFieldsMarkup(){return`<div class="fields"><div class="field"><label>Default detail mode</label><select id="policyDefaultDetailMode"><option value="busy" ${state.preferences.defaultDetailMode==="busy"?"selected":""}>busy</option><option value="subject" ${state.preferences.defaultDetailMode==="subject"?"selected":""}>subject</option><option value="full" ${state.preferences.defaultDetailMode==="full"?"selected":""}>full</option></select></div><div class="field"><label>Default visibility</label><select id="policyDefaultVisibility"><option value="private" ${state.preferences.defaultVisibility==="private"?"selected":""}>private</option><option value="default" ${state.preferences.defaultVisibility==="default"?"selected":""}>default</option></select></div><div class="field"><label>Family detail mode</label><select id="policyFamilyDetailMode"><option value="busy" ${state.preferences.familyDetailMode==="busy"?"selected":""}>busy</option><option value="subject" ${state.preferences.familyDetailMode==="subject"?"selected":""}>subject</option><option value="full" ${state.preferences.familyDetailMode==="full"?"selected":""}>full</option></select></div><div class="field"><label>Family visibility</label><select id="policyFamilyVisibility"><option value="private" ${state.preferences.familyVisibility==="private"?"selected":""}>private</option><option value="default" ${state.preferences.familyVisibility==="default"?"selected":""}>default</option></select></div></div><div class="toggle"><label class="check"><input id="policyCopyLocationToFamily" type="checkbox" ${state.preferences.copyLocationToFamily?"checked":""}><span>Copy location to family targets</span></label><label class="check"><input id="policyCopyDescriptionToFamily" type="checkbox" ${state.preferences.copyDescriptionToFamily?"checked":""}><span>Copy description to family targets</span></label><label class="check"><input id="policyPreserveOriginalTimezone" type="checkbox" ${state.preferences.preserveOriginalTimezone?"checked":""}><span>Preserve original timezone</span></label></div>`}
function setupStepsPanel(){return`<div class="list"><div class="step ${state.workspaceAccountExists?"done":state.setupStep==="account"?"active":""}"><div class="eyebrow">Step 1</div><strong>Workspace Account</strong><p>Create a simple Paranoid Keeper workspace account. After that, the same browser becomes the management console.</p></div><div class="step ${state.accounts.length?"done":state.setupStep==="calendars"?"active":""}"><div class="eyebrow">Step 2</div><strong>Calendars</strong><p>Add every work, personal, family, or contract calendar Marvin should mirror. Each one gets its own prefix.</p></div><div class="step ${state.setupStep==="access"?"active":""}"><div class="eyebrow">Step 3</div><strong>Link Accounts</strong><p>Use Marvin to open the real provider sign-in, then validate each linked account before the Paranoid Keeper runtime starts.</p></div><div class="step ${state.setupStep==="rules"?"active":""}"><div class="eyebrow">Step 4</div><strong>Privacy And Keeper Runtime</strong><p>Keep mirrors private by default, relax detail for family targets when you choose, then start the Paranoid Keeper runtime.</p></div></div>`}
function renderAuth(){const createMode=!state.workspaceAccountExists||!state.requiresLogin;app.innerHTML=`<section class="grid"><section class="panel"><div class="chip">Setup Assistant</div><h2>${createMode?"Create your Marvin account":"Sign in"}</h2><p>${createMode?"Start with one simple Paranoid Keeper workspace account. After that, Marvin walks you through calendars, account linking, privacy rules, and always-on sync.":"Sign in to the Paranoid Keeper workspace account that already exists for this deployment so you can manage linked calendars and automation."}</p>${setupStepsPanel()}</section><section class="panel"><h3>${createMode?"Create Workspace Account":"Sign In"}</h3><p class="meta">No solution picker. No deployment picker. Just Marvin.</p><div class="fields"><div class="field"><label>Marvin account name</label><input id="workspaceDisplayName" value="${esc(state.operator.marvinDisplayName)}" placeholder="Marvin Workspace"></div><div class="field"><label>Marvin account email</label><input id="workspaceEmail" value="${esc(state.operator.marvinEmail)}" placeholder="marvin@example.com"></div><div class="field"><label>Password</label><input id="workspacePassword" type="password" placeholder="Local Marvin password"></div></div><div class="actions"><button id="authPrimary">${createMode?"Create Workspace Account":"Sign In"}</button></div><div class="meta">Advanced workspace settings like profile ID, timezone, and sync window stay available after sign-in.</div></section></section>`;document.getElementById("authPrimary").addEventListener("click",()=>{void(createMode?createWorkspaceAccount():signInWorkspace())})}
function renderSetupAccountStage(){return`<div class="card"><h3>Workspace Account</h3><p>This is the only account Marvin needs from you directly. It owns the local workspace and unlocks the rest of setup.</p><div class="fields"><div class="field"><label>Marvin account name</label><input id="workspaceDisplayName" value="${esc(state.operator.marvinDisplayName)}" placeholder="Marvin Workspace"></div><div class="field"><label>Marvin account email</label><input id="workspaceEmail" value="${esc(state.operator.marvinEmail)}" placeholder="marvin@example.com"></div><div class="field"><label>Password</label><input id="workspacePassword" type="password" placeholder="${state.workspaceAccountExists?"Leave blank to keep the current password":"Local Marvin password"}"></div></div><details class="details-block" open><summary>Advanced workspace settings</summary><div class="fields"><div class="field"><label>Timezone</label><input id="workspaceTimezone" value="${esc(state.timezone)}"></div><div class="field"><label>Sync window (days)</label><input id="workspaceSyncWindowDays" type="number" min="1" max="365" value="${esc(state.syncWindowDays)}"></div><div class="field full"><label>Workspace profile ID</label><input id="workspaceProfileName" value="${esc(state.profileName)}" placeholder="marvin.local"></div></div><div class="meta">The workspace profile ID stays local. Most users can leave it as-is.</div></details><div class="actions"><button id="saveAccountStage">${state.workspaceAccountExists?"Update Workspace Account":"Create Workspace Account"}</button><button id="toCalendarsStage" class="secondary">Continue To Calendars</button></div></div>`}
function renderSetupCalendarsStage(){const editing=currentAccount();return`<div class="card"><h3>Calendars</h3><p>Add every calendar Marvin should mirror. Each calendar can originate meetings, gets its own prefix, and can carry its own privacy override.</p>${accountForm(editing)}<div class="actions"><button id="saveCalendar">${editing?"Update Calendar":"Add Calendar"}</button><button id="cancelCalendar" class="secondary">${editing?"Cancel Edit":"Clear Form"}</button><button id="continueToAccess" class="secondary">Continue To Linking</button></div><div class="meta">Save Marvin setup after you finish adding calendars so Marvin can generate real provider auth URLs.</div></div><div class="card"><h3>Configured Calendars</h3><p>${state.accounts.length?"Review prefixes, visibility defaults, and provider types before moving on to account linking.":"No calendars configured yet."}</p><div id="setupAccounts" class="list">${state.accounts.length?state.accounts.map(accountCard).join(""):'<div class="note"><strong>Action Required</strong><p>Add at least one calendar before Marvin can persist setup.</p></div>'}</div><div class="actions"><button id="saveWorkspaceFromCalendars">${state.setupPersisted?"Save Workspace Changes":"Save Marvin Setup"}</button></div></div>`}
function renderSetupAccessStage(){return`<div class="card"><h3>Link Accounts</h3><p>This is the main job in step 3. Use Marvin to open the real provider sign-in for each calendar, then run access validation until every calendar is Ready.</p><div class="note"><strong>How this works</strong><p>1. Save your calendar list. 2. Link each Microsoft, Outlook, Google, or Apple / CalDAV account from Marvin. 3. Run Check Access until every calendar shows Ready. 4. Only then start the Paranoid Keeper runtime.</p></div><div class="actions"><button id="validateAllFromSetup" class="secondary">Check All Calendars</button><button id="continueToRules" class="secondary">Continue To Privacy Rules</button></div><div id="setupAccessAccounts" class="list">${state.accounts.length?state.accounts.map(accountCard).join(""):'<div class="note">No calendars configured yet.</div>'}</div></div><div class="card"><h3>Admin prerequisites</h3><p>Only use this section if Marvin says Microsoft or Google access setup is still missing. Apple / CalDAV credentials stay on the calendar record itself.</p><div class="fields"><div class="field"><label>Microsoft client ID</label><input id="microsoftClientId" value="${esc(state.providerCredentials.microsoftClientId||"")}" placeholder="Application (client) ID"></div><div class="field"><label>Microsoft client secret</label><input id="microsoftClientSecret" type="password" placeholder="Leave blank to keep the stored secret"></div><div class="field"><label>Google client ID</label><input id="googleClientId" value="${esc(state.providerCredentials.googleClientId||"")}" placeholder="OAuth client ID"></div><div class="field"><label>Google client secret</label><input id="googleClientSecret" type="password" placeholder="Leave blank to keep the stored secret"></div></div><div class="actions"><button id="saveAccessSettings">Save Access Setup</button></div>${providerPlanSectionMarkup()}</div>`}
function resolveMirrorPolicy(target){const isFamily=target.scope==="family";return{visibility:target.inboundOverrides?.visibility||(isFamily?state.preferences.familyVisibility:state.preferences.defaultVisibility),detailMode:target.inboundOverrides?.detailMode||(isFamily?state.preferences.familyDetailMode:state.preferences.defaultDetailMode),copyLocation:Object.prototype.hasOwnProperty.call(target.inboundOverrides||{},"copyLocation")?Boolean(target.inboundOverrides.copyLocation):(isFamily?Boolean(state.preferences.copyLocationToFamily):true),copyDescription:Object.prototype.hasOwnProperty.call(target.inboundOverrides||{},"copyDescription")?Boolean(target.inboundOverrides.copyDescription):(isFamily?Boolean(state.preferences.copyDescriptionToFamily):true)}}
function mirrorPreviewMarkup(){if((state.accounts||[]).length<2)return`<div class="note"><strong>Mirror preview:</strong><p>Add at least two calendars before Marvin can preview cross-calendar sync behavior.</p></div>`;return state.accounts.map((source)=>{const targets=state.accounts.filter((target)=>target.id!==source.id);return`<div class="note"><strong>${esc(source.label)} mirrors to ${targets.length} target${targets.length===1?"":"s"}</strong><div class="list">${targets.map((target)=>{const policy=resolveMirrorPolicy(target);const sampleSubject=policy.detailMode==="busy"?"Busy":`${source.sourcePrefix||defaultPrefix(source.label,source.provider)}Example meeting`;return`<div class="note"><strong>${esc(source.label)} -> ${esc(target.label)}</strong><p>Visibility: ${esc(policy.visibility)} | Detail: ${esc(policy.detailMode)} | Subject preview: ${esc(sampleSubject)}</p><p>Location: ${policy.copyLocation?"copied":"hidden"} | Description: ${policy.copyDescription?"copied":"hidden"} | Timezone: ${state.preferences.preserveOriginalTimezone?"preserved from source":"workspace timezone"}</p></div>`}).join("")}</div></div>`}).join("")}
function renderSetupRulesStage(){return`<div class="card"><h3>Privacy Rules</h3><p>Business targets stay private by default. Family targets can receive more visible detail when you choose it.</p>${rulesFieldsMarkup()}<div class="actions"><button id="saveRulesSetup">Save Workspace Rules</button><button id="openConsoleAfterRules" class="secondary">Open Management Console</button></div></div><div class="card"><h3>Mirror Preview</h3><p>Review exactly how Marvin will mirror events from every source calendar to every other target before you start the Paranoid Keeper runtime.</p><div class="list">${mirrorPreviewMarkup()}</div></div><div class="card"><h3>Keeper Runtime Readiness</h3><p>Do not trust background sync until every configured calendar is linked and validated.</p><div class="list">${readinessSummary()}</div><div class="list">${runtimeSummary()}</div><div class="actions"><button id="startAutomationFromSetup" ${automationReady()?"":"disabled"}>Start Keeper Runtime</button><button id="refreshRuntimeFromSetup" class="secondary">Refresh Keeper Runtime</button></div></div>`}
function renderSetupMain(){if(state.setupStep==="account")return renderSetupAccountStage();if(state.setupStep==="calendars")return renderSetupCalendarsStage();if(state.setupStep==="access")return renderSetupAccessStage();return renderSetupRulesStage()}
function bindSetupNav(){document.querySelectorAll("[data-setup-step]").forEach((button)=>button.addEventListener("click",()=>{state.setupStep=button.dataset.setupStep;state.editingAccountId="";render()}))}
function bindSetupStageActions(){if(state.setupStep==="account"){document.getElementById("saveAccountStage")?.addEventListener("click",async()=>{if(state.workspaceAccountExists){syncWorkspaceFromDom();if(state.setupPersisted){await saveSetup(false)}else{setStatus("Marvin account details staged locally. Continue to calendars.","ok");state.setupStep="calendars";render()}return}const created=await createWorkspaceAccount();if(created)state.setupStep="calendars"});document.getElementById("toCalendarsStage")?.addEventListener("click",()=>{syncWorkspaceFromDom();state.setupStep="calendars";render()});return}if(state.setupStep==="calendars"){document.getElementById("saveCalendar")?.addEventListener("click",saveLocalAccount);document.getElementById("cancelCalendar")?.addEventListener("click",()=>{state.editingAccountId="";render()});document.getElementById("continueToAccess")?.addEventListener("click",async()=>{if(!state.setupPersisted&&state.accounts.length){await saveSetup(false)}state.setupStep="access";render()});document.getElementById("saveWorkspaceFromCalendars")?.addEventListener("click",()=>{void saveSetup(false)});bindAccountActions(document.getElementById("setupAccounts"));return}if(state.setupStep==="access"){document.getElementById("saveAccessSettings")?.addEventListener("click",()=>{void saveProviderAccessOnly()});document.getElementById("validateAllFromSetup")?.addEventListener("click",()=>{void validateAllConnections()});document.getElementById("continueToRules")?.addEventListener("click",()=>{syncWorkspaceFromDom();state.setupStep="rules";render()});document.getElementById("loadMicrosoftPlan")?.addEventListener("click",()=>{void loadProviderPlan("microsoft")});document.getElementById("loadGooglePlan")?.addEventListener("click",()=>{void loadProviderPlan("google")});bindAccountActions(document.getElementById("setupAccessAccounts"));return}document.getElementById("saveRulesSetup")?.addEventListener("click",()=>{void saveSetup(false)});document.getElementById("openConsoleAfterRules")?.addEventListener("click",()=>{void saveSetup(true)});document.getElementById("startAutomationFromSetup")?.addEventListener("click",()=>{void startRuntime()});document.getElementById("refreshRuntimeFromSetup")?.addEventListener("click",()=>{void refreshRuntimeStatus()})}
function renderSetup(){const savedWorkspace=state.setupPersisted;app.innerHTML=`<section class="grid"><section class="panel"><div class="chip">${savedWorkspace?"Workspace Settings":"Setup Assistant"}</div><h2>${savedWorkspace?"Workspace Settings":"First-Run Setup"}</h2><p>${savedWorkspace?"Update your Paranoid Keeper workspace account, calendars, account linking, or privacy rules without dropping the workspace back into staging mode.":"Marvin walks you through account creation, calendar setup, account linking, privacy rules, and Paranoid Keeper runtime readiness in a single guided flow."}</p>${setupStepsPanel()}<div class="tabs"><button class="tab ${state.setupStep==="account"?"active":""}" data-setup-step="account">Workspace Account</button><button class="tab ${state.setupStep==="calendars"?"active":""}" data-setup-step="calendars">Calendars</button><button class="tab ${state.setupStep==="access"?"active":""}" data-setup-step="access">Link Accounts</button><button class="tab ${state.setupStep==="rules"?"active":""}" data-setup-step="rules">Privacy And Keeper Runtime</button></div><div class="note"><strong>${savedWorkspace?"Workspace Saved":"Action Required"}</strong><p>${savedWorkspace?"These edits apply to the live Paranoid Keeper workspace. Use Back To Management Console when you want to return to day-to-day operations.":"Until you save Marvin setup, provider auth URLs and long-running Paranoid Keeper sync are not available yet."}</p></div></section><section class="panel">${renderSetupMain()}${savedWorkspace?'<div class="actions"><button id="closeWorkspaceSettings" class="ghost">Back To Management Console</button></div>':""}</section></section>`;bindSetupNav();bindSetupStageActions();document.getElementById("closeWorkspaceSettings")?.addEventListener("click",()=>{state.workspaceSettingsOpen=false;render()})}
function renderConsole(){const stats=state.connectionSummary?.summary||{total:state.accounts.length};const ready=state.readinessSummary?.ready||0;const required=state.readinessSummary?.actionRequired||Math.max((stats.total||0)-ready,0);const tab=state.tab;app.innerHTML=`<section class="panel"><div class="toolbar"><div><div class="chip">Management Console</div><h2>${esc(state.operator.marvinDisplayName||"Marvin")} Management Console</h2><p>Manage calendars, account links, privacy rules, and the Paranoid Keeper runtime from one place after first-run setup is complete.</p></div><div class="right"><button id="refreshState" class="secondary">Refresh Marvin State</button><button id="openSetup" class="secondary">Workspace Settings</button><button id="signOut" class="ghost">Sign Out</button></div></div><div class="stats"><div class="stat"><span class="chip">Calendars</span><strong>${stats.total||0}</strong><div class="meta">Total configured calendars</div></div><div class="stat"><span class="chip">Ready</span><strong>${ready}</strong><div class="meta">Linked and validated</div></div><div class="stat"><span class="chip">Action Required</span><strong>${required}</strong><div class="meta">Need access setup, linking, or validation</div></div><div class="stat"><span class="chip">Keeper Runtime</span><strong>${state.runtimeProcess?.running?"On":"Off"}</strong><div class="meta">Current runtime status</div></div></div><div class="grid"><div class="card" style="grid-column:1/-1"><h3>Next Steps</h3><p>Marvin should make the next real action obvious before you trust background sync.</p><div class="list">${nextSteps().length?nextSteps().map((step)=>`<div class="note"><strong>Action Required</strong><p>${esc(step)}</p></div>`).join(""):'<div class="note"><strong>Ready</strong><p>Every linked calendar currently passes Marvin\'s readiness checks for the Paranoid Keeper runtime.</p></div>'}</div></div><div class="card"><h3>Marvin Workspace</h3><div class="list">${workspaceSummary()}</div></div><div class="card"><h3>Readiness Summary</h3><div class="list">${readinessSummary()}</div></div></div><div class="tabs"><button class="tab ${tab==="overview"?"active":""}" data-tab="overview">Overview</button><button class="tab ${tab==="calendars"?"active":""}" data-tab="calendars">Calendars</button><button class="tab ${tab==="providers"?"active":""}" data-tab="providers">Link Accounts</button><button class="tab ${tab==="rules"?"active":""}" data-tab="rules">Privacy Rules</button><button class="tab ${tab==="automation"?"active":""}" data-tab="automation">Keeper Runtime</button><button class="tab ${tab==="activity"?"active":""}" data-tab="activity">Activity Log</button></div><div id="tabBody" class="grid"></div></section>`;document.querySelectorAll("[data-tab]").forEach((button)=>button.addEventListener("click",()=>{state.tab=button.dataset.tab;render()}));document.getElementById("refreshState").addEventListener("click",()=>{void reloadConfig()});document.getElementById("openSetup").addEventListener("click",()=>{state.workspaceSettingsOpen=true;state.setupStep="account";state.editingAccountId="";render()});document.getElementById("signOut").addEventListener("click",()=>{void signOutWorkspace()});renderTabBody()}
function renderTabBody(){const body=document.getElementById("tabBody");if(!body)return;if(state.tab==="overview"){body.innerHTML=`<div class="card" style="grid-column:1/-1"><h3>Calendars</h3><p>Add, edit, remove, link, relink, validate, and review every calendar Marvin manages from one list.</p><div class="actions"><button id="validateAll">Check All Calendars</button></div><div class="meta">The Paranoid Keeper runtime stays blocked until every calendar below is linked and passes validation.</div><div id="consoleAccounts" class="list">${state.accounts.length?state.accounts.map(accountCard).join(""):'<div class="note">No calendars configured yet.</div>'}</div></div>`;document.getElementById("validateAll").addEventListener("click",()=>{void validateAllConnections()});bindAccountActions(document.getElementById("consoleAccounts"));return}if(state.tab==="calendars"){const editing=currentAccount();body.innerHTML=`<div class="card"><h3>Manage Calendars</h3><p>Add new calendars, fix prefixes, or change per-target visibility overrides.</p>${accountForm(editing)}<div class="actions"><button id="saveAccount">${editing?"Update Calendar":"Add Calendar"}</button><button id="cancelAccount" class="secondary">${editing?"Cancel Edit":"Clear Form"}</button><button id="saveWorkspace" class="ghost">Save Workspace Setup</button></div></div><div class="card"><h3>Saved Calendars</h3><p>Each account below shows access setup and link status so you can tell what Marvin still needs.</p><div id="consoleAccounts" class="list">${state.accounts.length?state.accounts.map(accountCard).join(""):'<div class="note">No calendars configured yet.</div>'}</div></div>`;document.getElementById("saveAccount").addEventListener("click",saveLocalAccount);document.getElementById("cancelAccount").addEventListener("click",()=>{state.editingAccountId="";render()});document.getElementById("saveWorkspace").addEventListener("click",()=>{void saveSetup(false)});bindAccountActions(document.getElementById("consoleAccounts"));return}if(state.tab==="providers"){body.innerHTML=`<div class="card"><h3>Link Accounts</h3><p>Use Marvin to open the real provider sign-in for each calendar, then validate until every calendar is Ready.</p><div class="actions"><button id="validateAll" class="secondary">Check All Calendars</button></div><div class="meta">If Marvin says access setup is missing, open the admin details section below for Microsoft or Google app requirements.</div><div id="consoleAccounts" class="list">${state.accounts.length?state.accounts.map(accountCard).join(""):'<div class="note">No calendars configured yet.</div>'}</div></div><div class="card"><h3>Admin prerequisites</h3><p>Only use this section when Marvin still needs Microsoft or Google app settings before it can open provider sign-in.</p><div class="fields"><div class="field"><label>Microsoft client ID</label><input id="microsoftClientId" value="${esc(state.providerCredentials.microsoftClientId||"")}" placeholder="Application (client) ID"></div><div class="field"><label>Microsoft client secret</label><input id="microsoftClientSecret" type="password" placeholder="Leave blank to keep the stored secret"></div><div class="field"><label>Google client ID</label><input id="googleClientId" value="${esc(state.providerCredentials.googleClientId||"")}" placeholder="OAuth client ID"></div><div class="field"><label>Google client secret</label><input id="googleClientSecret" type="password" placeholder="Leave blank to keep the stored secret"></div></div><div class="actions"><button id="saveProviderAccess">Save Access Setup</button></div>${providerPlanSectionMarkup()}</div>`;document.getElementById("saveProviderAccess").addEventListener("click",()=>{void saveProviderAccessOnly()});document.getElementById("validateAll").addEventListener("click",()=>{void validateAllConnections()});document.getElementById("loadMicrosoftPlan")?.addEventListener("click",()=>{void loadProviderPlan("microsoft")});document.getElementById("loadGooglePlan")?.addEventListener("click",()=>{void loadProviderPlan("google")});bindAccountActions(document.getElementById("consoleAccounts"));return}if(state.tab==="rules"){body.innerHTML=`<div class="card"><h3>Privacy Rules</h3><p>Private by default for business targets. Family targets can receive more visible detail when you choose it.</p>${rulesFieldsMarkup()}<div class="actions"><button id="saveRules">Save Rules</button></div></div><div class="card"><h3>Mirror Preview</h3><p>Review exactly how Marvin will mirror events from every source calendar to every other target before you trust the Paranoid Keeper runtime.</p><div class="list">${mirrorPreviewMarkup()}</div></div>`;document.getElementById("saveRules").addEventListener("click",()=>{void saveSetup(false)});return}if(state.tab==="automation"){body.innerHTML=`<div class="card"><h3>Keeper Runtime</h3><p>Start or stop the Paranoid Keeper sync runtime and review the latest runtime state.</p><div class="list">${runtimeSummary()}</div><div class="actions"><button id="startAutomation" ${automationReady()?"":"disabled"}>Start Keeper Runtime</button><button id="stopAutomation" class="secondary">Stop Keeper Runtime</button><button id="refreshRuntime" class="secondary">Refresh Keeper Runtime</button></div></div><div class="card"><h3>Readiness Gate</h3><p>The Paranoid Keeper runtime stays blocked until every calendar below is linked and validated.</p><div class="list">${readinessSummary()}</div></div>`;document.getElementById("startAutomation").addEventListener("click",()=>{void startRuntime()});document.getElementById("stopAutomation").addEventListener("click",()=>{void stopRuntime()});document.getElementById("refreshRuntime").addEventListener("click",()=>{void refreshRuntimeStatus()});return}body.innerHTML=`<div class="card" style="grid-column:1/-1"><h3>Activity Log</h3><p>Local Marvin activity is intentionally plain so you can inspect what the browser is doing.</p><pre class="log">${esc(JSON.stringify({profileName:state.profileName,readinessSummary:state.readinessSummary,runtimeStatus:state.runtimeStatus,subscriptionState:state.subscriptionState},null,2))}</pre></div>`}
function render(){if(!state.signedIn){renderAuth();return}if(!state.setupPersisted||state.workspaceSettingsOpen){renderSetup();return}renderConsole()}
async function bootstrap(){const result=await getJson("/marvin-api/bootstrap");state.workspaceAccountExists=Boolean(result.hasOperator);state.signedIn=Boolean(result.authenticated);state.requiresLogin=Boolean(result.requiresLogin);state.setupStep=result.hasOperator?"calendars":"account";if(result.operator){state.operator.marvinDisplayName=result.operator.displayName||"";state.operator.marvinEmail=result.operator.email||""}if(result.authenticated&&result.config){applyConfig(result.config);setStatus("Marvin loaded. Review linked calendars, provider access, link status, and Paranoid Keeper runtime status before trusting sync.","ok")}else if(result.authenticated){setStatus("Signed in to Marvin. Continue with calendars and provider setup.","ok")}else if(result.requiresLogin){setStatus("Sign in to continue.","warn")}else{setStatus("Create your Marvin account to begin setup.","warn")}render()}
bootstrap().catch((error)=>{setStatus(error.message||"Unable to load Marvin.","bad");renderAuth()})






